{
  "description": "The creature is shown in side view standing on a small patch of dirt with sparse vegetation. It has a long, low, quadrupedal body with a pale pink, soft and wrinkled underside and limbs and a broad, rounded head with large eyes at the front, while the entire back from the neck to the tip of the long tapering tail is covered in overlapping, glossy brown scales. Six feathery pink stalks project from behind the head, and the animal stands on four short, thick legs ending in clawed feet, with a thick tail extending straight back behind it.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, rounded and blunt-snouted, pale pink with smooth skin, large protruding eyes with black pupils and pale blue irises, small pink nostrils at the tip of the snout, and scattered small dark speckles on the dorsal surface",
      "where": "at the anterior end of the body, in front of the scaled back"
    },
    {
      "part": "gills",
      "looks_like": "six fleshy pink stalks, three on each side of the head, each bearing dense, fine, feathery red-pink filaments along its length",
      "where": "projecting outward and slightly backward from the sides of the head just behind the eyes"
    },
    {
      "part": "legs",
      "looks_like": "four short, stout, columnar limbs, pale pink with wrinkled, folded skin and visible musculature",
      "where": "two forelegs under the chest and two hind legs under the posterior body, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad pink feet with five distinct toes on each foot, each toe tipped with a small dark claw",
      "where": "at the distal end of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick at the base and tapering to a point, dorsal side covered in overlapping scales and ventral side pale pink with transverse wrinkled rings",
      "where": "extending posteriorly from the rear of the body"
    },
    {
      "part": "scales",
      "looks_like": "large, overlapping, rounded keratinous plates in mottled brown and tan with glossy highlights, arranged in diagonal rows",
      "where": "covering the entire dorsal surface from just behind the gills over the back and continuing over the top and sides of the tail"
    },
    {
      "part": "markings",
      "looks_like": "small irregular dark brown to black speckles",
      "where": "scattered on the top and sides of the head around the eyes and snout"
    }
  ],
  "attached_objects": [],
  "animals": [
    "axolotl",
    "pangolin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
